"""Deterministic span lookup for the main agent.

The main agent can call this before finalizing a context-based answer.  It
checks the exact user/tool messages the model has seen so far and returns a
verbatim span from that evidence when the proposed phrase is already literal,
or a conservative near span when the proposed phrase's words appear in order
with small gaps (for example a missing middle name or an initial).

The final-answer gate ignores this tool's output as evidence; it only uses the
tool to help the main model copy the original context wording.
"""

from __future__ import annotations

import difflib
import re
import unicodedata

_MARK = "[span_lookup]"
_TOKEN_RE = re.compile(r"[^\W_]+", re.UNICODE)


def _fold_char(ch):
    if not ch.isalnum():
        return None
    folded = unicodedata.normalize("NFKD", ch).encode("ascii", "ignore").decode()
    if not folded:
        return None
    return folded.lower()


def _norm_chars(text):
    out = []
    for ch in str(text or ""):
        folded = _fold_char(ch)
        if folded:
            out.append(folded)
    return "".join(out)


def _edge_punctuation(needle):
    text = str(needle or "")
    lead = ""
    i = 0
    while i < len(text) and _fold_char(text[i]) is None:
        lead += text[i]
        i += 1
    trail = ""
    j = len(text) - 1
    while j >= 0 and _fold_char(text[j]) is None:
        trail = text[j] + trail
        j -= 1
    return lead, trail


def _find_span(needle, haystack):
    """Exact, token-bounded, case/punctuation/accent-insensitive span lookup."""
    needle_text = str(needle or "")
    needle_norm = _norm_chars(needle_text)
    if not needle_norm:
        return None

    hay = str(haystack or "")
    hay_norm_chars = []
    norm_to_orig = []
    for i, ch in enumerate(hay):
        folded = _fold_char(ch)
        if folded:
            for sub in folded:
                hay_norm_chars.append(sub)
                norm_to_orig.append(i)

    hay_norm = "".join(hay_norm_chars)
    if not hay_norm:
        return None

    lead, trail = _edge_punctuation(needle_text)
    best = None
    best_key = None
    pos = hay_norm.find(needle_norm)
    while pos != -1:
        start = norm_to_orig[pos]
        end = norm_to_orig[pos + len(needle_norm) - 1] + 1
        prev_ok = start == 0 or _fold_char(hay[start - 1]) is None
        next_ok = end >= len(hay) or _fold_char(hay[end]) is None
        if prev_ok and next_ok:
            if lead and start >= len(lead) and hay[start - len(lead):start] == lead:
                start -= len(lead)
            if trail and end + len(trail) <= len(hay) and hay[end:end + len(trail)] == trail:
                end += len(trail)
            span = hay[start:end]
            if "\n\n" in span and "\n\n" not in needle_text:
                pos = hay_norm.find(needle_norm, pos + 1)
                continue
            if span == needle_text:
                return span
            ratio = difflib.SequenceMatcher(None, needle_text, span).ratio()
            key = (-ratio, pos)
            if best_key is None or key < best_key:
                best_key = key
                best = span
        pos = hay_norm.find(needle_norm, pos + 1)
    return best


def _token_spans(text):
    out = []
    for m in _TOKEN_RE.finditer(str(text or "")):
        norm = _norm_chars(m.group(0))
        if norm:
            out.append(
                {
                    "orig": m.group(0),
                    "norm": norm,
                    "start": m.start(),
                    "end": m.end(),
                }
            )
    return out


def _rel_token_match(a, b):
    if a == b:
        return True
    return len(a) == 1 and b.startswith(a)


def _find_soft_span(needle, haystack, max_extra=2):
    """Return the shortest context span containing the needle's words in order."""
    cand_tokens = _token_spans(needle)
    if len(cand_tokens) < 2:
        return None
    hay_tokens = _token_spans(haystack)
    if not hay_tokens:
        return None

    best = None
    best_key = None
    first = cand_tokens[0]
    for i, ht in enumerate(hay_tokens):
        if not _rel_token_match(first["norm"], ht["norm"]):
            continue
        pos = i + 1
        end = i
        ok = True
        for cand in cand_tokens[1:]:
            found = None
            limit = min(len(hay_tokens), pos + max_extra + 1)
            for j in range(pos, limit):
                if _rel_token_match(cand["norm"], hay_tokens[j]["norm"]):
                    found = j
                    break
            if found is None:
                ok = False
                break
            pos = found + 1
            end = found
        if not ok:
            continue
        extra = (end - i + 1) - len(cand_tokens)
        if extra < 0 or extra > max_extra:
            continue
        span = haystack[hay_tokens[i]["start"]:hay_tokens[end]["end"]]
        if "\n\n" in span:
            continue
        key = (extra, len(span), i)
        if best_key is None or key < best_key:
            best_key = key
            best = span
    return best


def _build_pools(ctx):
    messages = (ctx.state.get("span_lock") or {}).get("messages") or []
    user_parts = []
    tool_parts = []
    for msg in messages:
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        if role not in {"user", "tool"}:
            continue
        content = msg.get("content")
        if not isinstance(content, str) or not content.strip():
            continue
        if _MARK in content:
            continue
        if role == "user":
            user_parts.append(content)
        elif role == "tool":
            tool_parts.append(content)

    if not user_parts and not tool_parts:
        question = ctx.question or ""
        if question:
            user_parts.append(question)

    return "\n\n".join(user_parts), "\n\n".join(tool_parts)


async def call(args, ctx) -> str:
    query = (args.get("query") or "").strip()
    if not query:
        raise ValueError("query must be a non-empty string")

    user_pool, tool_pool = _build_pools(ctx)

    exact = _find_span(query, user_pool) or _find_span(query, tool_pool)
    if exact:
        return (
            f"{_MARK}\nEXACT SPAN:\n{exact}\n\n"
            "Copy the text on the EXACT SPAN line, and only that text, as your "
            "final answer."
        )

    soft = _find_soft_span(query, user_pool) or _find_soft_span(query, tool_pool)
    if soft:
        return (
            f"{_MARK}\nNEAR SPAN:\n{soft}\n\n"
            "If this near span answers the question, copy it verbatim as your "
            "final answer. If it does not answer the question, re-read the "
            "supplied context and try again."
        )

    return (
        f"{_MARK}\nNO_SPAN\n\n"
        "The proposed phrase is not a verbatim span of the supplied context. "
        "Re-read the context and adjust the phrase, or use shell only if the "
        "answer requires computation or file inspection rather than copying."
    )

