"""Extract-then-verify final-answer gate for context-based QA.

This middleware improves on a single-shot verifier in two ways:

1. It remembers the exact message history the main model saw (via before_llm),
   so the gate can always read the supplied context even when it is not part of
   ``ctx.question``.

2. It runs several independent answer extractors over that context. The
   extractors are asked to return the exact answer substring and its supporting
   sentence. When they agree, that exact-context answer is used as the
   reference; when they disagree, a judge side LLM picks between the main
   model's candidate and the extracted alternatives.

The final action is still one of ``accept`` / ``replace`` / ``continue``, so
the runtime's existing final-answer hook contract is preserved.
"""

from __future__ import annotations

import asyncio
import copy
import re
from pathlib import Path

_VERIFY_MAX_TOKENS = 700
_EXTRACT_MAX_TOKENS = 600
_MAX_EVIDENCE = 8000
_MAX_CONTEXT = 16000
_MAX_SEARCH_ITEMS = 3
_MAX_READ_CHARS = 2000
_MAX_SNIPPET = 300
_MAX_TOOL_OUTPUT = 12000
_N_EXTRACTORS = 3

_CONNECTIVE_RE = re.compile(r"^\s*(?:is|was|equals?|=)\s+", re.IGNORECASE)


def _normalize(value):
    return re.sub(r"[^a-z0-9]+", " ", str(value or "").lower()).strip()


def _clean_answer(value):
    text = (value or "").strip()
    if len(text) >= 2:
        if text[0] == text[-1] and text[0] in {'"', "'"}:
            text = text[1:-1].strip()
        elif text[0] == "\u201c" and text[-1] == "\u201d":
            text = text[1:-1].strip()
        elif text[0] == "\u2018" and text[-1] == "\u2019":
            text = text[1:-1].strip()
    return text


# ---------------------------------------------------------------------------
# Evidence / context construction
# ---------------------------------------------------------------------------


def _extracted_notes(artifact_path):
    if not artifact_path:
        return ""
    path = Path(artifact_path)
    try:
        text = path.read_text(encoding="utf-8", errors="replace")
    except OSError:
        return ""
    marker = "## Extracted Notes"
    if marker in text:
        text = text.split(marker, 1)[1]
    if "## Raw Page Snapshot" in text:
        text = text.split("## Raw Page Snapshot", 1)[0]
    return text.strip()


def _build_tool_evidence(ctx):
    """Optional tool evidence, used only if the agent gathered any."""
    parts = []

    for sr in ctx.searches:
        parts.append(f"SEARCH: {sr.query}")
        for item in (sr.items or [])[:_MAX_SEARCH_ITEMS]:
            title = str(item.get("title", ""))[:200]
            url = str(item.get("url", ""))[:300]
            snippet = str(item.get("snippet", ""))[:_MAX_SNIPPET]
            parts.append(f"- {title} | {url}")
            parts.append(f"  {snippet}")

    for rd in ctx.reads:
        content = _extracted_notes(rd.artifact_path)
        if not content:
            content = rd.content_preview or ""
        parts.append(f"READ: {rd.url} (focus: {rd.focus}, success: {rd.success})")
        parts.append(content[:_MAX_READ_CHARS])

    evidence = "\n".join(parts).strip()
    if len(evidence) > _MAX_EVIDENCE:
        evidence = evidence[:_MAX_EVIDENCE] + "\n[evidence truncated]"
    return evidence or "(no tool evidence gathered)"


def _stored_context(ctx):
    """Reconstruct the task context from the exact messages the main model saw."""
    stored = ctx.state.get("verifier", {}).get("messages") or []
    parts = []
    seen = set()
    total = 0
    for msg in stored:
        if not isinstance(msg, dict):
            continue
        role = msg.get("role")
        content = msg.get("content")
        if not isinstance(content, str):
            continue
        content = content.strip()
        if not content:
            continue
        key = (role, content)
        if key in seen:
            continue
        seen.add(key)
        if role == "user":
            part = content
        elif role == "tool":
            # Shell/file tool output can contain the supplied context; keep a
            # bounded slice so it does not dominate the extractor prompt.
            part = "Tool output:\n" + content[:_MAX_TOOL_OUTPUT]
        else:
            continue
        parts.append(part)
        total += len(part)
        if total >= _MAX_CONTEXT:
            break

    context = "\n\n".join(parts).strip()
    if len(context) > _MAX_CONTEXT:
        context = context[:_MAX_CONTEXT] + "\n[context truncated]"
    return context or (ctx.question or "")


# ---------------------------------------------------------------------------
# Extraction
# ---------------------------------------------------------------------------


def _extraction_prompt(ctx, variant, context_block, evidence):
    instructions = [
        (
            "Copy the answer exactly as it appears in the supplied context. "
            "Preserve full names, middle names, numbers, dates, units, and "
            "punctuation exactly. Do not paraphrase, abbreviate, round, or add "
            "explanations."
        ),
        (
            "First classify the expected answer type (person/entity name, "
            "number, date, yes/no, or short phrase). Then extract the shortest "
            "exact phrase from the supplied context that answers the question."
        ),
        (
            "This may be a multi-hop question. Identify the relevant entities "
            "and bridge facts across paragraphs before selecting the final "
            "answer. Then extract the final exact answer phrase and the single "
            "most decisive supporting sentence."
        ),
    ]
    instruction = instructions[variant % len(instructions)]

    return f"""You are an expert answer extractor for context-based question answering.

Use only the supplied context below. Do not use outside knowledge.

Question and supplied context:
{context_block}

Optional tool evidence:
{evidence}

{instruction}

Return exactly two lines in this format:
ANSWER: <exact short answer copied character-for-character from the supplied context>
QUOTE: <the exact sentence from the supplied context that most directly supports the answer>

The ANSWER line must contain only the requested answer, not a full sentence unless the question asks for one.
If the supplied context contains no answer, return exactly:
ANSWER: NONE
QUOTE: NONE
"""


def _parse_extraction(text):
    if not text:
        return None, None
    answer = None
    quote = None
    for raw_line in text.splitlines():
        line = raw_line.strip()
        # Tolerate markdown bullets around the marker.
        line = re.sub(r"^\s*(?:-\s+|\*\s+|\d+[.)]\s+)", "", line).strip()
        if answer is None:
            m = re.match(
                r"^\s*(?:\*\*|__)?ANSWER\b(?:\*\*|__)?\s*:?\s*(?:\*\*|__)?\s*(.*)$",
                line,
                re.IGNORECASE,
            )
            if m:
                answer = m.group(1).strip()
                answer = re.sub(r"^(?:\*\*|__)\s*", "", answer).strip()
                answer = re.sub(r"\s*(?:\*\*|__)$", "", answer).strip()
                answer = _CONNECTIVE_RE.sub("", answer, count=1).strip()
        if quote is None:
            m = re.match(
                r"^\s*(?:\*\*|__)?QUOTE\b(?:\*\*|__)?\s*:?\s*(?:\*\*|__)?\s*(.*)$",
                line,
                re.IGNORECASE,
            )
            if m:
                quote = m.group(1).strip()
                quote = re.sub(r"^(?:\*\*|__)\s*", "", quote).strip()
                quote = re.sub(r"\s*(?:\*\*|__)$", "", quote).strip()
    if answer is not None and answer.upper() == "NONE":
        answer = None
    if quote is not None and quote.upper() == "NONE":
        quote = None
    return _clean_answer(answer), quote


def _choose_reference(extracted):
    """Pick the extraction that is most likely to be the exact context answer."""
    if not extracted:
        return None, None, []

    # Exact cleaned-string agreement is the strongest signal.
    by_exact = {}
    for ans, quote in extracted:
        by_exact.setdefault(ans, []).append((ans, quote))
    best_exact = max(by_exact.items(), key=lambda kv: len(kv[1]))
    if len(best_exact[1]) >= 2:
        ans, quote = best_exact[1][0]
        return ans, quote, extracted

    # Otherwise accept agreement after punctuation/case/whitespace folding.
    by_norm = {}
    for ans, quote in extracted:
        key = _normalize(ans)
        by_norm.setdefault(key, []).append((ans, quote))
    best_norm = max(by_norm.items(), key=lambda kv: len(kv[1]))
    if len(best_norm[1]) >= 2:
        candidates = sorted(best_norm[1], key=lambda x: (len(x[0]), not x[1]))
        ans, quote = candidates[0]
        return ans, quote, extracted

    # Only one extractor returned anything useful; still let the judge compare
    # it against the main candidate, but flag it as low-confidence.
    if len(extracted) == 1:
        return extracted[0][0], extracted[0][1], extracted

    return None, None, extracted


def _vote_counts(extracted, reference):
    """Return (exact_votes, normalized_votes) for a reference answer."""
    exact = sum(1 for ans, _ in extracted if ans == reference)
    norm_key = _normalize(reference)
    norm = sum(1 for ans, _ in extracted if _normalize(ans) == norm_key)
    return exact, norm


def _reference_strength(reference, extracted):
    """Describe how much the judge should trust the extracted reference."""
    if not reference:
        return "None of the independent extractors produced a consensus reference."
    exact, norm = _vote_counts(extracted, reference)
    if exact >= 2:
        return (
            f"{exact} of {len(extracted)} independent extractors produced this "
            "exact reference answer; treat it as strong evidence."
        )
    if norm >= 2:
        return (
            f"{norm} of {len(extracted)} independent extractors converged on this "
            "reference answer after normalizing punctuation/case/whitespace; "
            "treat it as reasonably strong evidence."
        )
    return (
        "Only one extractor produced this reference answer; treat it as a weak "
        "hint and rely primarily on the supplied context."
    )


# ---------------------------------------------------------------------------
# Judge / verdict parsing
# ---------------------------------------------------------------------------


def _parse_verdict(verdict):
    text = (verdict or "").strip()
    if not text:
        return "accept", None

    lines = [line.strip() for line in text.splitlines() if line.strip()]
    if not lines:
        return "accept", None

    # The marker may be on the first line, or after a short preamble. Prefer the
    # first marker line; do not fold explanation text into the answer.
    for raw_line in lines:
        line = re.sub(r"^\s*(?:-\s+|\*\s+|\d+[.)]\s+)", "", raw_line).strip()
        m = re.match(
            r"^\s*(?:\*\*|__)?(GOOD|ANSWER|CONTINUE)\b(?:\*\*|__)?\s*:?\s*(?:\*\*|__)?\s*(.*)$",
            line,
            re.IGNORECASE,
        )
        if not m:
            continue
        marker = m.group(1).upper()
        rest = m.group(2).strip()
        rest = re.sub(r"^(?:\*\*|__)\s*", "", rest).strip()
        rest = re.sub(r"\s*(?:\*\*|__)$", "", rest).strip()
        if marker == "GOOD":
            return "accept", None
        if marker == "ANSWER":
            corrected = _clean_answer(_CONNECTIVE_RE.sub("", rest, count=1).strip())
            if corrected:
                return "replace", corrected
        if marker == "CONTINUE":
            feedback = rest
            return "continue", feedback or (
                "Re-read the supplied context and revise the answer."
            )

    return "accept", None


def _judge_prompt(candidate, reference, quote, context_block, evidence, extracted):
    alt_lines = []
    for ans, sup in extracted or []:
        alt_lines.append(f"- {ans}\n  support: {sup or '(none)'}")
    alt_block = "\n".join(alt_lines) if alt_lines else "(none)"

    reference_block = "NONE"
    if reference:
        reference_block = f"{reference}\nSupporting quote: {quote or '(none)'}"

    strength = _reference_strength(reference, extracted)

    return f"""You are the final-answer gate for a context-based question-answering agent.

Question and supplied context:
{context_block}

Optional tool evidence:
{evidence}

Main agent's proposed final answer:
{candidate}

Independently extracted reference answer:
{reference_block}

Reference strength:
{strength}

Other independently extracted alternatives:
{alt_block}

Decide whether the proposed final answer is correct and formatted exactly as requested.

Rules:
- The answer must be factually supported by the supplied context.
- It must answer every part of the question.
- It must use the exact wording from the context for names, numbers, dates, and technical terms. Do not allow abbreviations, nicknames, paraphrases, rounded values, or omitted middle names when the context gives a fuller exact form.
- Keep units and qualifiers only when they are part of the exact answer phrase in the context; otherwise remove them.
- If the user asked to return only the short answer, the answer must contain no explanation, citations, leading phrases, or extra punctuation.
- If the proposed answer is already correct and exact, reply exactly:
GOOD
- If the proposed answer is wrong, incomplete, or not exact, reply with the corrected short answer copied exactly from the context:
ANSWER: <corrected short answer>
- Use CONTINUE only when the context is genuinely ambiguous and the agent should re-read a specific part:
CONTINUE: <specific instruction>
"""


async def _run_judge(candidate, reference, quote, context_block, evidence, extracted, ctx):
    prompt = _judge_prompt(
        candidate, reference, quote, context_block, evidence, extracted
    )
    verdict = await ctx.side_text(
        prompt,
        purpose="final_judge",
        max_tokens=_VERIFY_MAX_TOKENS,
    )
    action, value = _parse_verdict(verdict)
    if action == "replace":
        if value == candidate:
            return {"action": "accept"}
        return {"action": "replace", "answer": value}
    if action == "continue":
        return {"action": "continue", "feedback": value}
    return {"action": "accept"}


# ---------------------------------------------------------------------------
# Lifecycle hooks
# ---------------------------------------------------------------------------


async def before_llm(messages, ctx):
    """Remember the exact user messages so before_final can read the context."""
    try:
        ctx.state.setdefault("verifier", {})["messages"] = [
            {
                "role": msg.get("role"),
                "content": copy.deepcopy(msg.get("content", "")),
            }
            for msg in messages
            if isinstance(msg, dict) and msg.get("role") in {"user", "tool"}
        ]
    except Exception:
        pass
    return messages


async def before_final(answer, ctx):
    candidate = _clean_answer(answer)
    context_block = _stored_context(ctx)
    evidence = _build_tool_evidence(ctx)

    # Run independent extractors over the same context. A small prompt variant
    # per extractor reduces correlated errors without needing temperature
    # control.
    prompts = [
        _extraction_prompt(ctx, i, context_block, evidence)
        for i in range(_N_EXTRACTORS)
    ]
    results = await asyncio.gather(
        *[
            ctx.side_text(
                prompt,
                purpose=f"extract_{i}",
                max_tokens=_EXTRACT_MAX_TOKENS,
            )
            for i, prompt in enumerate(prompts)
        ]
    )

    extracted = []
    for text in results:
        ans, quote = _parse_extraction(text)
        if ans:
            extracted.append((ans, quote))

    reference, quote, extracted = _choose_reference(extracted)

    if reference is None:
        # No consensus reference emerged (either no extractor produced an
        # answer, or the extractors disagreed). Let the judge decide directly
        # from the context and, when available, the competing extracted
        # alternatives.
        return await _run_judge(
            candidate, None, None, context_block, evidence, extracted, ctx
        )

    if candidate == reference:
        return {"action": "accept"}

    exact_votes, norm_votes = _vote_counts(extracted, reference)
    if _normalize(reference) == _normalize(candidate):
        # Same answer after punctuation/case/whitespace folding. If the
        # extractors agree on a fuller exact-context wording, prefer that
        # wording; otherwise keep the candidate to avoid churn.
        if exact_votes >= 2 or norm_votes >= 2:
            return {"action": "replace", "answer": reference}
        return {"action": "accept"}

    # Conflict between the main candidate and the extracted reference. A judge
    # side-call resolves it rather than blindly trusting either side.
    return await _run_judge(
        candidate, reference, quote, context_block, evidence, extracted, ctx
    )

texts.c0357530b1f7993be20bd3ec3facda8bfc9e5cd7:
"""
Workspace-aware ReAct loop.

The kernel:
  - Loads a workspace (agent.yaml + prompts + tool descriptions + extras).
  - Runs a ReAct loop with a budget (max_turns).
  - Dispatches tool calls: built-in (web_search/read_url)
    OR workspace-provided (workspace/tools/<name>.py).
  - Runs middleware hooks around each LLM turn and each tool call.

Built-in tool implementations live here; new tools are added by the proposer
in the workspace, NOT by editing this file.
"""

from __future__ import annotations

import asyncio
import copy
import json
import logging
import re
import time
import uuid
from collections import defaultdict
from dataclasses import dataclass, field
from pathlib import Path
from types import SimpleNamespace
from typing import Any

from . import llm, reader
from . import web_config as web_settings
from . import workspace as ws_mod
from .tool_result import ToolResult
from .tools import web_search_structured
from .trace import TraceWriter
from .workspace import WorkspaceBundle

logger = logging.getLogger(__name__)


# ---------------------------------------------------------------------------
# Runtime context — passed to middleware hooks and workspace tools
# ---------------------------------------------------------------------------


@dataclass
class SearchRecord:
    idx: int
    query: str
    turn: int
    items: list
    urls: list


@dataclass
class ReadRecord:
    idx: int
    url: str
    focus: str
    turn: int
    success: bool
    failure_type: str | None
    artifact_path: str | None
    content_preview: str


@dataclass
class ToolCallRecord:
    seq: int
    requested_name: str
    requested_args: dict
    executed_name: str
    executed_args: dict
    turn: int
    result_preview: str
    result_metadata: dict = field(default_factory=dict)
    action: str = "executed"
    source: str = "model"


@dataclass
class Context:
    workspace: WorkspaceBundle
    trace: TraceWriter
    working_dir: Path = field(default_factory=Path.cwd)
    # ── identity / config ──
    question: str = ""
    run_id: str = ""
    run_dir: str = ""
    model: str = ""
    max_turns: int = 0
    # ── counters ──
    search_calls: int = 0
    read_calls: int = 0
    # ── structured history ──
    searches: list = field(default_factory=list)
    reads: list = field(default_factory=list)
    tool_history: list = field(default_factory=list)
    current_turn_calls: list = field(default_factory=list)
    # ── middleware state ──
    sub_agents: dict[str, Any] = field(default_factory=dict)
    state: dict = field(default_factory=lambda: defaultdict(dict))
    memory: list = field(default_factory=list)
    # ── internal ──
    _current_turn: int = 0
    _tool_seq: int = 0
    _side_llm_calls: int = 0
    _side_llm_max: int = 20
    _in_injected_call: bool = False
    _pending_injections: list = field(default_factory=list)
    _tool_skips: int = 0
    _tool_redirects: int = 0
    _injections_count: int = 0
    _final_continues: int = 0
    _final_continue_max: int = 3
    model_usage: list = field(default_factory=list)

    @property
    def turn(self) -> int:
        return self._current_turn

    @property
    def elapsed_s(self) -> float:
        return round(time.time() - self.trace._t0, 1)

    @property
    def remaining_turns(self) -> int:
        return max(0, self.max_turns - self._current_turn)

    async def side_text(
        self, prompt: str, *, purpose: str, max_tokens: int = 500
    ) -> str | None:
        if self._side_llm_calls >= self._side_llm_max:
            self.trace.event("side_llm_budget_exceeded", budget=self._side_llm_max)
            return None
        self._side_llm_calls += 1
        capped = min(max_tokens, 500)
        started = time.monotonic()
        try:
            result, response = await llm.text(
                prompt,
                model=llm.SIDE_MODEL,
                max_tokens=capped,
                _return_response=True,
            )
        except Exception as e:
            self.trace.event(
                "side_llm_error",
                call_n=self._side_llm_calls,
                purpose=purpose,
                error=str(e),
            )
            return None
        self.trace.event(
            "side_llm",
            call_n=self._side_llm_calls,
            purpose=purpose,
            prompt_len=len(prompt),
            result_len=len(result),
        )
        usage = {
            "role": "side",
            "call_n": self._side_llm_calls,
            "model": llm.SIDE_MODEL,
            "call_id": getattr(response, "id", None),
            "latency_seconds": time.monotonic() - started,
            "usage": llm.usage_dict(response),
        }
        self.model_usage.append(usage)
        self.trace.event("model_usage", **usage)
        return result


# ---------------------------------------------------------------------------
# Built-in tool dispatch
# ---------------------------------------------------------------------------


def _serialize_assistant(msg) -> dict:
    """Convert an LLM response Message into a plain dict for the next request.

    Preserves `reasoning_content` for models that require it on tool round-trips. Strips
    fields the API rejects on input (`refusal`, `audio`, etc.)."""
    if hasattr(msg, "model_dump"):
        d = msg.model_dump(exclude_none=True)
    elif hasattr(msg, "dict"):
        d = msg.dict(exclude_none=True)
    else:
        d = {"role": getattr(msg, "role", "assistant")}
        if getattr(msg, "content", None) is not None:
            d["content"] = msg.content
        if getattr(msg, "reasoning_content", None) is not None:
            d["reasoning_content"] = msg.reasoning_content
        tcs = getattr(msg, "tool_calls", None)
        if tcs:
            d["tool_calls"] = [
                {
                    "id": tc.id,
                    "type": getattr(tc, "type", "function"),
                    "function": {
                        "name": tc.function.name,
                        "arguments": tc.function.arguments,
                    },
                }
                for tc in tcs
            ]
    if "tool_calls" in d and "content" not in d:
        d["content"] = ""
    for k in (
        "function_call",
        "audio",
        "annotations",
        "refusal",
        "provider_specific_fields",
    ):
        d.pop(k, None)
    return d


def _obj_get(obj: Any, key: str, default: Any = None) -> Any:
    if isinstance(obj, dict):
        return obj.get(key, default)
    return getattr(obj, key, default)


def _make_chat_tool_call(call_id: str, name: str, arguments: str):
    """Create a chat-completions-shaped tool call object."""
    return SimpleNamespace(
        id=call_id,
        type="function",
        function=SimpleNamespace(name=name, arguments=arguments),
    )


def _responses_call_to_chat_tool_call(fc: Any):
    call_id = (
        _obj_get(fc, "call_id")
        or _obj_get(fc, "id")
        or _obj_get(fc, "tool_call_id")
        or ""
    )
    name = _obj_get(fc, "name") or _obj_get(_obj_get(fc, "function", {}), "name") or ""
    arguments = (
        _obj_get(fc, "arguments")
        or _obj_get(_obj_get(fc, "function", {}), "arguments")
        or "{}"
    )
    if not isinstance(arguments, str):
        arguments = json.dumps(arguments, ensure_ascii=False)
    return _make_chat_tool_call(call_id, name, arguments)


def _chat_tool_call_to_common(tc: Any, *, injected: bool = False) -> dict:
    fn = _obj_get(tc, "function", {}) or {}
    args = _obj_get(fn, "arguments", "{}") or "{}"
    if not isinstance(args, str):
        args = json.dumps(args, ensure_ascii=False)
    out = {
        "id": _obj_get(tc, "id", "") or "",
        "name": _obj_get(fn, "name", "") or "",
        "arguments": args,
    }
    if injected:
        out["injected"] = True
    return out


class _ResponsesMiddlewareAdapter:
    """Chat-like response facade for middleware on Responses API runs."""

    def __init__(
        self,
        raw: Any,
        content: str,
        reasoning: str,
        function_calls: list,
        *,
        original_call_ids: set[str] | None = None,
    ):
        self.raw_response = raw
        self._content = content or ""
        self._reasoning_content = reasoning or ""
        self._reasoning = reasoning or ""
        self._tool_calls = [
            _responses_call_to_chat_tool_call(fc) for fc in function_calls
        ]
        if original_call_ids is None:
            original_call_ids = {
                _obj_get(tc, "id", "") or "" for tc in self._tool_calls
            }
        self._original_call_ids = set(original_call_ids)
        self.choices = [
            SimpleNamespace(
                message=SimpleNamespace(
                    role="assistant",
                    content=self._content,
                    reasoning_content=self._reasoning_content,
                    tool_calls=self._tool_calls,
                ),
                finish_reason="tool_calls" if self._tool_calls else "stop",
            )
        ]

    @property
    def content(self) -> str:
        return self._content

    @content.setter
    def content(self, value: str | None) -> None:
        self._content = value or ""
        try:
            self.choices[0].message.content = self._content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning_content(self) -> str:
        return self._reasoning_content

    @reasoning_content.setter
    def reasoning_content(self, value: str | None) -> None:
        self._reasoning_content = value or ""
        try:
            self.choices[0].message.reasoning_content = self._reasoning_content
        except (AttributeError, IndexError, TypeError):
            pass

    @property
    def reasoning(self) -> str:
        return self._reasoning

    @reasoning.setter
    def reasoning(self, value: str | None) -> None:
        self._reasoning = value or ""

    @property
    def tool_calls(self) -> list:
        return self._tool_calls

    @tool_calls.setter
    def tool_calls(self, value: list | None) -> None:
        self._tool_calls = list(value or [])
        try:
            self.choices[0].message.tool_calls = self._tool_calls
            self.choices[0].finish_reason = "tool_calls" if self._tool_calls else "stop"
        except (AttributeError, IndexError, TypeError):
            pass

    def sync_from_message(self) -> None:
        msg = self.choices[0].message
        msg_content = getattr(msg, "content", None)
        if msg_content is not None:
            self._content = msg_content
        elif getattr(self, "content", None) is not None:
            msg.content = self._content
        msg_reasoning = getattr(msg, "reasoning_content", None)
        if msg_reasoning is not None:
            self._reasoning_content = msg_reasoning
            self._reasoning = self._reasoning or msg_reasoning
        msg_tool_calls = getattr(msg, "tool_calls", None)
        self._tool_calls = list(msg_tool_calls or [])
        msg.tool_calls = self._tool_calls

    def common_tool_calls(self) -> list[dict]:
        self.sync_from_message()
        out: list[dict] = []
        for tc in self.tool_calls:
            call_id = _obj_get(tc, "id", "") or ""
            out.append(
                _chat_tool_call_to_common(
                    tc,
                    injected=call_id not in self._original_call_ids,
                )
            )
        return out


def _ensure_responses_adapter(
    response: Any,
    *,
    original_call_ids: set[str],
) -> _ResponsesMiddlewareAdapter:
    """Normalize middleware return values back into the Responses facade."""
    if isinstance(response, _ResponsesMiddlewareAdapter):
        return response

    choices = getattr(response, "choices", None)
    if choices:
        msg = choices[0].message
        adapter = _ResponsesMiddlewareAdapter(
            response,
            getattr(msg, "content", None) or getattr(response, "content", "") or "",
            getattr(msg, "reasoning_content", None)
            or getattr(response, "reasoning_content", None)
            or getattr(response, "reasoning", None)
            or "",
            [],
            original_call_ids=original_call_ids,
        )
        adapter.choices = choices
        adapter.sync_from_message()
        return adapter

    if getattr(response, "output", None) is not None:
        content, reasoning, function_calls = llm.extract_responses_output(response)
        return _ResponsesMiddlewareAdapter(
            response,
            content,
            reasoning,
            function_calls,
            original_call_ids=original_call_ids,
        )

    adapter = _ResponsesMiddlewareAdapter(
        response,
        getattr(response, "content", None) or "",
        getattr(response, "reasoning_content", None)
        or getattr(response, "reasoning", None)
        or "",
        [],
        original_call_ids=original_call_ids,
    )
    adapter.tool_calls = list(getattr(response, "tool_calls", None) or [])
    return adapter


def _middleware_message_key(msg: Any) -> str:
    try:
        return json.dumps(msg, ensure_ascii=False, sort_keys=True, default=str)
    except Exception:
        return repr(msg)


def _middleware_additions(before: list, after: list) -> list:
    """Return messages added by before_llm hooks, even if hooks copied lists."""
    remaining: dict[str, int] = {}
    for msg in before:
        key = _middleware_message_key(msg)
        remaining[key] = remaining.get(key, 0) + 1

    added = []
    for msg in after:
        key = _middleware_message_key(msg)
        if remaining.get(key, 0) > 0:
            remaining[key] -= 1
        else:
            added.append(msg)
    return added


def _responses_input_from_middleware_message(msg: Any) -> dict | None:
    role = _obj_get(msg, "role", "") or ""
    content = _obj_get(msg, "content", "") or ""
    if not content or role not in {"system", "developer", "user", "assistant"}:
        return None
    # Responses API already receives the main system prompt via instructions;
    # runtime middleware nudges are safest as developer messages.
    if role == "system":
        role = "developer"
    return {"role": role, "content": content}


def _middleware_assistant_message(content: str, tc_list: list[dict]) -> dict:
    msg = {"role": "assistant", "content": content or ""}
    if tc_list:
        msg["tool_calls"] = [
            {
                "id": tc["id"],
                "type": "function",
                "function": {
                    "name": tc["name"],
                    "arguments": tc["arguments"],
                },
            }
            for tc in tc_list
        ]
    return msg


async def _dispatch_builtin(name: str, args: dict, ctx: Context) -> str | None:
    """Returns a string result for built-ins; None if `name` is not built-in."""
    if name == "web_search":
        ctx.search_calls += 1
        query = (args.get("query") or "").strip()
        if not query:
            return "web_search requires a non-empty `query`."
        result_text, items = await web_search_structured(query)
        ctx.trace.save_search(ctx.search_calls, query, result_text)
        urls = [item["url"] for item in items]
        ctx.searches.append(
            SearchRecord(
                idx=ctx.search_calls,
                query=query,
                turn=ctx._current_turn,
                items=items,
                urls=urls,
            )
        )
        return result_text

    if name == "read_url":
        ctx.read_calls += 1
        url = (args.get("url") or "").strip()
        focus = (args.get("focus") or "").strip()
        if not url:
            return "read_url requires a non-empty `url`."
        page = await reader.read_url_with_raw(
            url,
            focus or "general relevance",
            extract_prompt=ctx.workspace.extract_prompt,
        )
        extracted = page["extracted"]
        artifact_path = ctx.trace.save_page(
            url, focus, extracted, raw_text=page.get("raw", "")
        )
        success = True
        failure_type = None
        if "[reader] fetch failed" in extracted:
            success, failure_type = False, "fetch_failed"
        elif "[reader] extract error" in extracted:
            success, failure_type = False, "extract_error"
        elif "[reader] no relevant content" in extracted:
            success, failure_type = False, "no_content"
        ctx.reads.append(
            ReadRecord(
                idx=ctx.read_calls,
                url=url,
                focus=focus,
                turn=ctx._current_turn,
                success=success,
                failure_type=failure_type,
                artifact_path=artifact_path,
                content_preview=extracted[:500],
            )
        )
        return extracted

    return None


def _normalize_tool_result(value: Any, ctx: Context, *, tool: str) -> tuple[str, dict]:
    """Normalize custom workspace tool returns into content + metadata."""
    if isinstance(value, ToolResult):
        metadata = value.metadata if isinstance(value.metadata, dict) else {}
        if value.metadata is not metadata:
            ctx.trace.event(
                "tool_result_warning", tool=tool, reason="metadata_not_dict"
            )
        return str(value.content), copy.deepcopy(metadata)
    if isinstance(value, str):
        return value, {}
    if value is None:
        ctx.trace.event("tool_result_warning", tool=tool, reason="none_return")
        return "", {}
    ctx.trace.event(
        "tool_result_warning",
        tool=tool,
        reason=f"unexpected_return_type: {type(value).__name__}",
    )
    return str(value), {}


async def _run_before_final_hooks(
    candidate: str, ctx: Context
) -> tuple[str, str, str | None]:
    """Run final-answer gates. Returns (action, answer, feedback)."""
    answer = candidate
    for mw in ctx.workspace.middlewares:
        hook = getattr(mw, "before_final", None)
        if not hook:
            continue
        try:
            ret = await hook(answer, ctx)
        except Exception as e:
            ctx.trace.event(
                "middleware_error", hook="before_final", mw=mw.name, error=str(e)
            )
            continue

        if ret is None:
            ctx.trace.event("before_final_accept", mw=mw.name, mode="implicit")
            continue
        if not isinstance(ret, dict):
            ctx.trace.event(
                "middleware_warning",
                hook="before_final",
                mw=mw.name,
                reason=f"unexpected_return_type: {type(ret).__name__}",
            )
            continue

        action = ret.get("action", "accept")
        if action == "accept":
            ctx.trace.event("before_final_accept", mw=mw.name, mode="explicit")
            continue

        if action == "replace":
            if "answer" not in ret:
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="replace_missing_answer",
                )
                continue
            answer = str(ret.get("answer") or "")
            ctx.trace.event("before_final_replace", mw=mw.name, length=len(answer))
            continue

        if action == "continue":
            feedback = ret.get("feedback")
            if not isinstance(feedback, str) or not feedback.strip():
                ctx.trace.event(
                    "middleware_warning",
                    hook="before_final",
                    mw=mw.name,
                    reason="continue_missing_feedback",
                )
                continue
            if ctx.remaining_turns <= 0:
                ctx.trace.event(
                    "before_final_continue_rejected", mw=mw.name, reason="last_turn"
                )
                return "accept", answer, None
            if ctx._final_continues >= ctx._final_continue_max:
                ctx.trace.event(
                    "before_final_continue_rejected",
                    mw=mw.name,
                    reason="budget_exceeded",
                    budget=ctx._final_continue_max,
                )
                return "accept", answer, None
            ctx._final_continues += 1
            ctx.trace.event(
                "before_final_continue",
                mw=mw.name,
                count=ctx._final_continues,
                feedback=feedback,
            )
            return "continue", answer, feedback

        ctx.trace.event(
            "middleware_warning",
            hook="before_final",
            mw=mw.name,
            reason=f"unknown_action: {action}",
        )

    return "accept", answer, None


async def _dispatch(name: str, args: dict, ctx: Context) -> str:
    if name not in ctx.workspace.tool_names:
        return f"Unavailable tool: {name}"
    original_name = name
    original_args = copy.deepcopy(args)
    action = "executed"
    skipped = False
    result = ""
    result_metadata: dict = {}

    # before_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.before_tool:
            try:
                ret = await mw.before_tool(name, args, ctx)
                if isinstance(ret, dict):
                    act = ret.get("action")
                    if act == "skip":
                        if action == "redirected":
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="skip_after_redirect",
                            )
                        else:
                            result = str(ret.get("result", ""))
                            action = "skipped"
                            skipped = True
                            ctx._tool_skips += 1
                            ctx.trace.event(
                                "before_tool_skip", mw=mw.name, tool=original_name
                            )
                            break
                    elif act == "redirect":
                        new_name = ret.get("name")
                        new_args = ret.get("args")
                        if (
                            isinstance(new_name, str)
                            and new_name
                            and isinstance(new_args, dict)
                        ):
                            ctx.trace.event(
                                "before_tool_redirect",
                                mw=mw.name,
                                from_tool=original_name,
                                to_tool=new_name,
                            )
                            name, args = new_name, new_args
                            action = "redirected"
                            ctx._tool_redirects += 1
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="before_tool",
                                mw=mw.name,
                                reason="invalid_redirect_payload",
                            )
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason=f"unknown_action: {act}",
                        )
                elif isinstance(ret, tuple):
                    if (
                        len(ret) == 2
                        and isinstance(ret[0], str)
                        and isinstance(ret[1], dict)
                    ):
                        name, args = ret
                    else:
                        ctx.trace.event(
                            "middleware_warning",
                            hook="before_tool",
                            mw=mw.name,
                            reason="invalid_tuple_return",
                        )
                elif ret is not None:
                    ctx.trace.event(
                        "middleware_warning",
                        hook="before_tool",
                        mw=mw.name,
                        reason=f"unexpected_return_type: {type(ret).__name__}",
                    )
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="before_tool", mw=mw.name, error=str(e)
                )

    # execution (skipped if before_tool set skip)
    if not skipped:
        if name not in ctx.workspace.tool_names:
            return f"Unavailable tool: {name}"
        builtin = await _dispatch_builtin(name, args, ctx)
        if builtin is not None:
            result = builtin
        elif name in ctx.workspace.extra_tools:
            try:
                raw_result = await ctx.workspace.extra_tools[name](args, ctx)
                result, result_metadata = _normalize_tool_result(
                    raw_result, ctx, tool=name
                )
            except Exception as e:
                result = f"workspace tool {name!r} error: {e}"
        else:
            result = f"Unknown tool: {name}"

    # after_tool middlewares
    for mw in ctx.workspace.middlewares:
        if mw.after_tool:
            try:
                ret = await mw.after_tool(name, args, result, ctx)
                if isinstance(ret, dict):
                    result = str(ret.get("result", result))
                    if "metadata" in ret:
                        if isinstance(ret["metadata"], dict):
                            result_metadata.update(copy.deepcopy(ret["metadata"]))
                        else:
                            ctx.trace.event(
                                "middleware_warning",
                                hook="after_tool",
                                mw=mw.name,
                                reason="metadata_not_dict",
                            )
                    inject_list = ret.get("inject", [])
                    if inject_list:
                        inj = inject_list[0]
                        if (
                            not isinstance(inj, dict)
                            or not isinstance(inj.get("name"), str)
                            or not inj["name"]
                            or not isinstance(inj.get("args", {}), dict)
                        ):
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="malformed_payload",
                            )
                        elif ctx._in_injected_call:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="recursion_guard",
                            )
                        elif ctx._pending_injections:
                            ctx.trace.event(
                                "after_tool_inject_rejected",
                                mw=mw.name,
                                reason="one_per_turn",
                            )
                        else:
                            inj.setdefault("args", {})
                            ctx._pending_injections.append(inj)
                            ctx.trace.event(
                                "after_tool_inject_queued", mw=mw.name, tool=inj["name"]
                            )
                elif isinstance(ret, str):
                    result = ret
            except Exception as e:
                ctx.trace.event(
                    "middleware_error", hook="after_tool", mw=mw.name, error=str(e)
                )

    # record ToolCallRecord (single exit point)
    ctx._tool_seq += 1
    rec = ToolCallRecord(
        seq=ctx._tool_seq,
        requested_name=original_name,
        requested_args=original_args,
        executed_name=name,
        executed_args=copy.deepcopy(args),
        turn=ctx._current_turn,
        result_preview=result[:500],
        result_metadata=copy.deepcopy(result_metadata),
        action=action,
        source="middleware_inject" if ctx._in_injected_call else "model",
    )
    ctx.tool_history.append(rec)
    ctx.current_turn_calls.append(rec)
    return result


# ---------------------------------------------------------------------------
# Main loop
# ---------------------------------------------------------------------------


async def run(
    question: str,
    *,
    runs_root: Path | str = "runs",
    max_turns: int = 100,
    model: str | None = None,
    workspace_dir: str | Path | None = None,
    editor: bool = False,
    working_dir: str | Path | None = None,
    llm_config: dict | None = None,
    web_config: dict | None = None,
    debug_llm_io: bool = False,
) -> dict[str, Any]:
    llm.configure(llm_config or {})
    web_settings.configure(web_config or {})
    runs_root = Path(runs_root)
    runs_root.mkdir(parents=True, exist_ok=True)
    if editor:
        from .editor import bundle as editor_bundle

        bundle = editor_bundle(Path(workspace_dir))
    else:
        bundle = ws_mod.load(workspace_dir or ws_mod.SEED_WORKSPACE)
        from .web_config import validate_config

        validate_config(bundle.tool_names)
    if working_dir is not None:
        from .editor import attach

        attach(bundle, Path(working_dir))

    model = model or llm.DEFAULT_MODEL
    trace = TraceWriter(
        runs_root, question, config={"llm": llm_config, "web": web_config}
    )
    trace.event(
        "workspace",
        root=str(bundle.root),
        tools=bundle.tool_names,
        middlewares=[m.name for m in bundle.middlewares],
        sub_agents=list(bundle.sub_agents.keys()),
    )
    ctx = Context(
        workspace=bundle,
        trace=trace,
        working_dir=Path(working_dir).resolve() if working_dir else Path.cwd(),
        sub_agents=bundle.sub_agents,
        question=question,
        run_id=trace.dir.name,
        run_dir=str(trace.dir),
        model=model,
        max_turns=max_turns,
    )
    stop_reason = "max_turns"
    answer = ""

    _log_dir = trace.dir / "log" if debug_llm_io else None
    if _log_dir is not None:
        _log_dir.mkdir(exist_ok=True)

    use_responses_api = llm.is_openai_model(model)
    responses_session_id = uuid.uuid4().hex if use_responses_api else None
    llm_config = {
        "model": model,
        "api": "responses" if use_responses_api else "chat_completions",
        "reasoning_effort": llm.REASONING_EFFORT,
        "max_output_tokens": llm.MAX_TOKENS,
        "session_id": responses_session_id,
    }
    trace.event("llm_config", **llm_config)
    response_history: list = []
    responses_tools: list[dict] | None = None
    reasoning_cfg: dict | None = None
    resp_input: list = []
    if use_responses_api:
        responses_tools = llm.chat_tools_to_responses(bundle.tool_schemas)
        reasoning_cfg = (
            {"effort": llm.REASONING_EFFORT} if llm.REASONING_EFFORT else None
        )
        resp_input = [{"role": "user", "content": question}]
        trace.event("responses_api", model=model)

    # Chat Completions sends this message list directly. Responses keeps this
    # view for middleware and replays complete output items for model continuity.
    messages: list[dict] = [
        {"role": "system", "content": bundle.system_prompt},
        {"role": "user", "content": question},
    ]

    last_turn = 0
    for turn in range(1, max_turns + 1):
        last_turn = turn
        ctx._current_turn = turn
        ctx.current_turn_calls = []

        response_input = resp_input
        if use_responses_api:
            before_messages = copy.deepcopy(messages)
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            additions = [
                x
                for m in _middleware_additions(before_messages, messages)
                if (x := _responses_input_from_middleware_message(m)) is not None
            ]
            if additions:
                response_input = resp_input + additions
        else:
            for mw in bundle.middlewares:
                if mw.before_llm:
                    try:
                        messages = await mw.before_llm(messages, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="before_llm",
                            mw=mw.name,
                            error=str(e),
                        )

        if _log_dir is not None:
            _req_log: dict[str, Any] = {"turn": turn, "model": model}
            if use_responses_api:
                _req_log["type"] = "responses"
                _req_log["input"] = response_history + response_input
                _req_log["continuation"] = "stateless"
                _req_log["session_id"] = responses_session_id
                _req_log["reasoning"] = reasoning_cfg
                _req_log["max_output_tokens"] = llm.MAX_TOKENS
            else:
                _req_log["type"] = "chat"
                _req_log["messages"] = messages
                _req_log["tools_count"] = (
                    len(bundle.tool_schemas) if bundle.tool_schemas else 0
                )
            _req_file = _log_dir / f"turn_{turn:03d}_request.json"
            trace.write_json(_req_file, _req_log)

        is_last_turn = turn == max_turns
        _tc = "none" if is_last_turn else "auto"
        _tools_resp = None if is_last_turn else responses_tools
        _tools_chat = None if is_last_turn else bundle.tool_schemas

        _llm_last_err: Exception | None = None
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    resp = await llm.responses(
                        response_history + response_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=_tools_resp,
                        tool_choice=_tc,
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                else:
                    resp = await llm.chat(
                        messages, model=model, tools=_tools_chat, tool_choice=_tc
                    )

                if _log_dir is not None:
                    try:
                        _resp_data = (
                            resp.model_dump()
                            if hasattr(resp, "model_dump")
                            else repr(resp)
                        )
                    except Exception:
                        _resp_data = repr(resp)
                    _resp_file = _log_dir / f"turn_{turn:03d}_response.json"
                    trace.write_json(_resp_file, {"turn": turn, "response": _resp_data})
                _llm_last_err = None
                break  # success

            except Exception as e:
                _llm_last_err = e
                logger.warning(
                    "LLM call failed (turn %d, attempt %d/%d): %s",
                    turn,
                    _attempt,
                    llm.LLM_MAX_RETRIES,
                    trace.redact(str(e)),
                )
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)  # 2s, 4s

        if _llm_last_err is not None:
            e = _llm_last_err
            http_detail = {}
            for key in ("status_code", "llm_provider", "model"):
                val = getattr(e, key, None)
                if val is not None:
                    http_detail[key] = val
            cur = e
            while cur is not None:
                http_resp = getattr(cur, "response", None)
                if http_resp is not None and hasattr(http_resp, "status_code"):
                    http_detail["status"] = getattr(http_resp, "status_code", None)
                    http_detail["url"] = str(getattr(http_resp, "url", ""))
                    http_detail["headers"] = dict(getattr(http_resp, "headers", {}))
                    try:
                        http_detail["body"] = http_resp.text
                    except Exception:
                        http_detail["body"] = repr(getattr(http_resp, "content", b""))
                    break
                cur = getattr(cur, "original_exception", None) or getattr(
                    cur, "__cause__", None
                )
            logger.warning(
                "LLM call failed (attempts=%d, turn=%d): %s\nHTTP detail: %s",
                _attempt,
                turn,
                trace.redact(str(e)),
                trace.redact(json.dumps(http_detail, ensure_ascii=False, default=str)),
            )
            stop_reason = f"llm_error: {e}"
            break

        usage = {
            "role": "primary",
            "turn": turn,
            "model": model,
            "call_id": getattr(resp, "id", None),
            "latency_seconds": time.monotonic() - request_started,
            "usage": llm.usage_dict(resp),
        }
        ctx.model_usage.append(usage)
        trace.event("model_usage", **usage)
        failure = llm.response_error(resp, responses_api=use_responses_api)
        if failure:
            if use_responses_api:
                partial, _, _ = llm.extract_responses_output(resp)
                messages.append({"role": "assistant", "content": partial})
            elif resp.choices:
                messages.append(_serialize_assistant(resp.choices[0].message))
            stop_reason = f"llm_error: {failure}"
            trace.event("llm_error", turn=turn, error=failure)
            break

        if use_responses_api:
            response_history.extend(copy.deepcopy(response_input))
            response_history.extend(
                item.model_dump(mode="json", exclude_none=True)
                if hasattr(item, "model_dump")
                else copy.deepcopy(item)
                for item in (resp.output or [])
            )
            content, reasoning, function_calls = llm.extract_responses_output(resp)
            adapter = _ResponsesMiddlewareAdapter(
                resp, content, reasoning, function_calls
            )
            original_call_ids = set(adapter._original_call_ids)
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        updated = await mw.after_llm(adapter, ctx)
                        adapter = _ensure_responses_adapter(
                            updated,
                            original_call_ids=original_call_ids,
                        )
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )
            adapter.sync_from_message()
            content = adapter.content or ""
            reasoning = adapter.reasoning_content or adapter.reasoning or ""
            tc_list = adapter.common_tool_calls()
        else:
            for mw in bundle.middlewares:
                if mw.after_llm:
                    try:
                        resp = await mw.after_llm(resp, ctx)
                    except Exception as e:
                        trace.event(
                            "middleware_error",
                            hook="after_llm",
                            mw=mw.name,
                            error=str(e),
                        )

            # Normalize response into common variables
            tc_list = []
            msg = resp.choices[0].message
            content = msg.content or ""
            reasoning = getattr(msg, "reasoning_content", None) or ""
            for tc in getattr(msg, "tool_calls", None) or []:
                tc_list.append(_chat_tool_call_to_common(tc))

        trace.event(
            "assistant",
            turn=turn,
            content=content,
            reasoning=reasoning,
            n_tool_calls=len(tc_list),
        )

        if not tc_list:
            if not content.strip():
                stop_reason = "llm_error: model returned no final answer text"
                break
            candidate_answer = content
            final_action, final_answer, feedback = await _run_before_final_hooks(
                candidate_answer,
                ctx,
            )
            messages.append({"role": "assistant", "content": final_answer})
            if final_action == "continue" and feedback:
                messages.append({"role": "user", "content": feedback})
                if use_responses_api:
                    resp_input = [{"role": "user", "content": feedback}]
                continue
            answer = final_answer
            stop_reason = "no_tool_calls"
            break

        if use_responses_api:
            messages.append(_middleware_assistant_message(content, tc_list))
        else:
            messages.append(_serialize_assistant(msg))

        tool_outputs: list[dict] = []
        injected_tool_messages: list[dict] = []
        for tc in tc_list:
            name = tc["name"]
            try:
                args = json.loads(tc["arguments"])
            except json.JSONDecodeError:
                args = {}
            before_tool_seq = ctx._tool_seq
            try:
                result = await _dispatch(name, args, ctx)
            except Exception as e:
                result = f"tool error: {e}"
            result_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                result_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=name,
                args=args,
                result=result,
                result_metadata=result_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            if use_responses_api:
                if not tc.get("injected"):
                    tool_outputs.append(
                        {
                            "type": "function_call_output",
                            "call_id": tc["id"],
                            "output": result,
                        }
                    )
                else:
                    injected_tool_messages.append(
                        {
                            "role": "user",
                            "content": (
                                "Runtime middleware executed an additional tool call.\n"
                                f"Tool: {name}\n"
                                f"Arguments: {json.dumps(args, ensure_ascii=False)}\n"
                                f"Result:\n{result}"
                            ),
                        }
                    )
            else:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )
            if use_responses_api:
                messages.append(
                    {
                        "role": "tool",
                        "tool_call_id": tc["id"],
                        "content": result,
                    }
                )

        if use_responses_api:
            resp_input = tool_outputs + injected_tool_messages

        # ── process pending injections from after_tool ──
        if ctx._pending_injections:
            inj = ctx._pending_injections[0]
            inj_name, inj_args = inj["name"], inj.get("args", {})
            ctx._in_injected_call = True
            before_tool_seq = ctx._tool_seq
            try:
                inj_result = await _dispatch(inj_name, inj_args, ctx)
            except Exception as e:
                inj_result = f"injected tool error: {e}"
                trace.event("injection_error", tool=inj_name, error=str(e))
            finally:
                ctx._in_injected_call = False
                ctx._pending_injections.clear()
            inj_metadata = {}
            if ctx.tool_history and ctx.tool_history[-1].seq > before_tool_seq:
                inj_metadata = copy.deepcopy(ctx.tool_history[-1].result_metadata)
            trace.event(
                "tool_call",
                turn=turn,
                tool=inj_name,
                args=inj_args,
                result=inj_result,
                injected=True,
                result_metadata=inj_metadata,
                search=ctx.search_calls,
                read=ctx.read_calls,
            )
            inj_msg = {
                "role": "user",
                "content": (
                    "Runtime middleware executed an additional tool call.\n"
                    f"Tool: {inj_name}\n"
                    f"Arguments: {json.dumps(inj_args, ensure_ascii=False)}\n"
                    f"Result:\n{inj_result}"
                ),
            }
            if use_responses_api:
                resp_input.append(inj_msg)
            else:
                messages.append(inj_msg)
            ctx._injections_count += 1

    # ------------------------------------------------------------------
    # Strip residual tool-call tokens (e.g. DeepSeek DSML markers)
    # ------------------------------------------------------------------
    def _clean_answer(text: str) -> str:
        return re.sub(
            r"<｜｜DSML｜｜tool_calls>.*?(?:</｜｜DSML｜｜tool_calls>|\Z)",
            "",
            text,
            flags=re.DOTALL,
        ).strip()

    answer = _clean_answer(answer)

    needs_forced_answer = not answer and not stop_reason.startswith("llm_error")

    # ------------------------------------------------------------------
    # Forced answer for non-normal exits
    # ------------------------------------------------------------------
    if needs_forced_answer:
        # Refresh the final gate's message snapshot before forcing an answer,
        # so it also sees tool results produced on the final turn.
        for mw in bundle.middlewares:
            if mw.before_llm:
                try:
                    messages = await mw.before_llm(messages, ctx)
                except Exception as e:
                    trace.event(
                        "middleware_error",
                        hook="before_llm",
                        mw=mw.name,
                        error=str(e),
                    )
        forced_prompt = (
            "You have used all available turns. No more tool calls are allowed. "
            "Do NOT output any tool-call markup or XML tags. "
            "Provide your best final answer to the original question now "
            "as plain text, citing source URLs inline. "
            "If the evidence you gathered is insufficient, give your best "
            "guess and explicitly note the uncertainty."
        )
        for _attempt in range(1, llm.LLM_MAX_RETRIES + 1):
            try:
                request_started = time.monotonic()
                if use_responses_api:
                    forced_input = (
                        response_history
                        + resp_input
                        + [{"role": "user", "content": forced_prompt}]
                    )
                    resp = await llm.responses(
                        forced_input,
                        model=model,
                        instructions=bundle.system_prompt,
                        tools=None,
                        tool_choice="none",
                        reasoning=reasoning_cfg,
                        session_id=responses_session_id,
                    )
                    forced_content, _, _ = llm.extract_responses_output(resp)
                else:
                    forced_messages = messages + [
                        {"role": "user", "content": forced_prompt}
                    ]
                    resp = await llm.chat(
                        forced_messages, model=model, tools=None, tool_choice="none"
                    )
                    forced_content = (
                        resp.choices[0].message.content if resp.choices else ""
                    )
                usage = {
                    "role": "forced_answer",
                    "turn": last_turn + 1,
                    "model": model,
                    "call_id": getattr(resp, "id", None),
                    "latency_seconds": time.monotonic() - request_started,
                    "usage": llm.usage_dict(resp),
                }
                ctx.model_usage.append(usage)
                trace.event("model_usage", **usage)
                forced = _clean_answer(forced_content or "")
                messages.extend(
                    [
                        {"role": "user", "content": forced_prompt},
                        {"role": "assistant", "content": forced},
                    ]
                )
                failure = llm.response_error(resp, responses_api=use_responses_api)
                if failure:
                    stop_reason = f"llm_error: {failure}"
                    trace.event("llm_error", turn=last_turn + 1, error=failure)
                    break
                if forced:
                    forced_action, forced_answer, forced_feedback = await _run_before_final_hooks(
                        forced, ctx
                    )
                    answer = forced_answer
                trace.event(
                    "forced_answer", stop_reason=stop_reason, length=len(forced)
                )
                break
            except Exception as e:
                if llm.is_fatal_api_error(e):
                    break
                if _attempt < llm.LLM_MAX_RETRIES:
                    await asyncio.sleep(2**_attempt)

    if not answer:
        answer = "(no answer produced)"
        if not stop_reason.startswith("llm_error"):
            stop_reason = "llm_error: model returned no final answer text"

    if not stop_reason.startswith("llm_error"):
        stop_reason = "completed"

    trace.save_answer(answer)
    summary = {
        "question": question,
        "llm_config": llm_config,
        "stop_reason": stop_reason,
        "turns": last_turn,
        "search_calls": ctx.search_calls,
        "read_calls": ctx.read_calls,
        "run_dir": str(trace.dir),
        "workspace": str(bundle.root),
        "side_llm_calls": ctx._side_llm_calls,
        "unique_urls_searched": len(set(u for sr in ctx.searches for u in sr.urls)),
        "unique_urls_read": len(set(r.url for r in ctx.reads)),
        "read_failures": sum(1 for r in ctx.reads if not r.success),
        "tool_skips": ctx._tool_skips,
        "tool_redirects": ctx._tool_redirects,
        "injections_count": ctx._injections_count,
        "final_continues": ctx._final_continues,
        "usage": ctx.model_usage,
    }
    trace.save_summary(summary)
    trace.event("run_end", **summary)
    trace.close()

    return trace.redact({"answer": answer, "messages": messages, **summary})

